import json
from typing import Any

def parse_json(text: str) -> dict[str, Any] | None:
    try:
        value = json.loads(text)
    except json.JSONDecodeError:
        return None
    return value if isinstance(value, dict) else None

assert parse_json('{"ok": true}') == {'ok': True}
assert parse_json('broken') is None

import time
from collections.abc import Callable
from typing import TypeVar
T = TypeVar('T')

def retry(operation: Callable[[], T], attempts: int = 3, delay: float = 0.2) -> T:
    if attempts < 1: raise ValueError('attempts kamida 1 bo‘lsin')
    for attempt in range(attempts):
        try: return operation()
        except (TimeoutError, ConnectionError):
            if attempt == attempts - 1: raise
            time.sleep(delay * (attempt + 1))
    raise RuntimeError('kutilmagan holat')

