import unittest

def clamp(value: int, low: int, high: int) -> int:
    if low > high: raise ValueError('low high’dan katta')
    return max(low, min(value, high))

class ClampTests(unittest.TestCase):
    def test_inside_range(self): self.assertEqual(clamp(5, 0, 10), 5)
    def test_low_boundary(self): self.assertEqual(clamp(-3, 0, 10), 0)
    def test_high_boundary(self): self.assertEqual(clamp(12, 0, 10), 10)

if __name__ == '__main__': unittest.main()

